<script setup lang="ts">
/**
 * TransactionNoField — the canonical "Transaction no." form field.
 *
 * A disabled, auto-generated number input whose LABEL carries a settings gear
 * that opens the shared NumberFormatSettingsModal (auto-numbering format). This
 * is the single source of truth for the pattern: every transaction FORM (sales
 * invoice / order / quote / delivery, credit memo + apply + refund, expense,
 * receipt, stock count, transfer, …) renders this instead of hand-rolling the
 * label + gear + modal. See docs/patterns/Form.md → "Transaction no. field".
 *
 *   <TransactionNoField field-id="apply-no" :next-number="nextTxNo" @save="onSave" />
 *
 * Only `field-id` (unique id stem) and `next-number` are required; the label,
 * modal title/caption and placeholder default to the "Transaction no." copy.
 */
import { ref, computed } from 'vue'
import { MpFormControl, MpFormLabel, MpInput, MpButton, MpIcon } from '@mekari/pixel3'
import NumberFormatSettingsModal, { type NumberFormatConfig } from '~/components/patterns/NumberFormatSettingsModal.vue'

const props = withDefaults(defineProps<{
  /** Unique id stem for the control + modal, e.g. "apply-no". */
  fieldId: string
  /** The next auto number shown in the settings modal, e.g. "Credit Memo #10090". */
  nextNumber: string | number
  /** Field label. Defaults to "Transaction no.". */
  label?: string
  /** Modal heading. Defaults to "Transaction no. settings". */
  title?: string
  /** One-liner under the modal heading. Defaults to the auto-generated copy. */
  caption?: string
  /** Existing saved formats for the modal's "Select existing format". */
  existingFormats?: { label: string; value: string }[]
  /** Value shown in the disabled input. Defaults to "Auto". */
  placeholder?: string
}>(), {
  label: '',
  title: '',
  caption: '',
  placeholder: '',
})
const emit = defineEmits<{ save: [NumberFormatConfig] }>()

const { t } = useLocale()
const open = ref(false)

const labelText = computed(() => props.label || t('Transaction no.'))
const titleText = computed(() => props.title || t('Transaction no. settings'))
const captionText = computed(() => props.caption || t('Transaction numbers are auto-generated by the system.'))
const valueText = computed(() => props.placeholder || t('Auto'))

function onSave(config: NumberFormatConfig) { open.value = false; emit('save', config) }
</script>

<template>
  <MpFormControl :id="fieldId" class="txno-field">
    <MpFormLabel>
      <span class="txno-label-row">
        {{ labelText }}
        <MpButton class="txno-label-icon" type="button" :aria-label="titleText" @click="open = true">
          <MpIcon name="settings" size="sm" />
        </MpButton>
      </span>
    </MpFormLabel>
    <MpInput :id="`${fieldId}-input`" :model-value="valueText" is-full-width is-disabled />
    <NumberFormatSettingsModal
      v-model:open="open"
      :title="titleText"
      :caption="captionText"
      :next-number="nextNumber"
      :existing-formats="existingFormats"
      @save="onSave"
    />
  </MpFormControl>
</template>

<style scoped>
.txno-label-row { display: inline-flex; align-items: center; gap: var(--mp-spacing-1); }
.txno-label-icon {
  display: inline-flex !important; align-items: center; justify-content: center;
  padding: 0 !important; border: none !important; background: none !important; min-width: 0 !important;
  cursor: pointer; color: var(--mp-text-secondary);
}
</style>
